using StrataLint.Scribe;
using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ObserverMemory.Algorithms.KBonacciAcquisition;

internal sealed class JointRewardFiberObstructionDocument : IScribeDocumentDefinition
{
    private const string Owner =
        "D5/S3/ObserverMemory/Algorithms/KBonacciAcquisition/JointRewardFiberObstruction.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Complete stopped rewards can prevent removal of A despite cellwise numerical dominance.",
        H("Joint reward-fiber obstruction"),
        Blocks(
            Describe.Lean(DescribeId.Create("joint-reward-word"),
                DeclarationHandle.Create(Owner + "Word"), H("Boolean word carrier"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For each natural L, Word L is the entire Boolean cube Fin L to Bool. No competitor word is omitted."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-point"),
                DeclarationHandle.Create(Owner + "point"), H("One actual atom"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every natural L, words a and b in Word L, and real t, point a t b is t when b equals a and zero otherwise."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-reading"),
                DeclarationHandle.Create(Owner + "reading"), H("Original stopped cell reward"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, real measure mu on Word L, original Schedule L and cell c in Fin 3, reading is the sum of mu over all words whose original StoppedCoefficientRealization.cell equals c. Empty and singleton schedules are included. Empty cells contribute zero."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-samereadings"),
                DeclarationHandle.Create(Owner + "SameReadings"), H("Equality before maximization"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and real measures mu and nu on Word L, SameReadings means equality of reading for every original stopped schedule and every cell. It asserts equality of individual rewards before any maxima, rather than equality of supports or costs."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-firstzero"),
                DeclarationHandle.Create(Owner + "FirstZero"), H("Original first-zero class"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, Boolean word b and address i in Fin L, FirstZero b i means b i is false and b h is true for every h strictly before i. The address i corresponds to original numerical output label i+1."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-fullscore"),
                DeclarationHandle.Create(Owner + "FullScore"), H("Independent full score coefficients"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, FullScore L contains independent real coefficient functions A, C and P on all Boolean words and a real terminal coefficient T. All coefficients are nonnegative. A, C and P at the all-true terminal word are normalized to zero; T is its independent coefficient. Thus every original nonterminal A/C/P coordinate remains available to competitors."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-baseline"),
                DeclarationHandle.Create(Owner + "baseline"), H("Zero-label measure"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y and word b, baseline y b is A(b)+P(b), plus T precisely at the all-true word. This is the actual zero-label reward measure."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-numerical"),
                DeclarationHandle.Create(Owner + "numerical"), H("Every numerical label"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y, address i and word b, numerical y i b is C(b)+P(b) when FirstZero b i holds, and zero otherwise. All L numerical labels are retained, in addition to the baseline label zero."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-coefficientmass"),
                DeclarationHandle.Create(Owner + "coefficientMass"), H("Total independent coefficient mass"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, coefficientMass y is the sum of A(b)+C(b)+P(b) over the entire cube, plus T. Shared P is counted exactly once."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-beta"),
                DeclarationHandle.Create(Owner + "beta"), H("Signed first-zero totals"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y and address i, beta y i is the sum of C(b)-A(b) over words in FirstZero class i."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-samefiber"),
                DeclarationHandle.Create(Owner + "SameFiber"), H("The complete reward fiber"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full scores y and z, SameFiber y z means equality of their entire beta functions, equality of all baseline stopped-cell readings, and equality of all numerical stopped-cell readings at every address. No cell-to-moment equivalence is assumed."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-baseword"),
                DeclarationHandle.Create(Owner + "baseWord"), H("The selected suffix 000 word"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and n,j,k,l in Fin L, baseWord sets precisely those four addresses to false and all other addresses to true. Under n<j<k<l this has first zero n and selected suffix bits 000. Original source indices are obtained by adding one to these zero-based addresses."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-singletonword"),
                DeclarationHandle.Create(Owner + "singletonWord"), H("Three selected singleton words"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and n,j,k,l,a in Fin L, singletonWord changes baseWord only at a, setting that bit to true. For a=j,k,l these are exactly the source suffix words 100,010,001."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-threepoints"),
                DeclarationHandle.Create(Owner + "threePoints"), H("The numerical source measure"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, addresses n,j,k,l, real t and word b, threePoints is the sum of point masses t at the three singletonWord words selected by j,k,l. Coincident atoms add, although the theorem requires strictly increasing selected addresses."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-witnessscore"),
                DeclarationHandle.Create(Owner + "witnessScore"), H("The actual four-word source score"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, n<j<k<l in Fin L, real t at least zero, witnessScore has A=t at baseWord, C=t at the three singletonWord words, P identically zero and T=0. Its nonnegativity and terminal normalization are proved. The original late-class condition is n.val at least 2; the rigidity theorem also holds without that restriction."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-rigidity"),
                DeclarationHandle.Create(Owner + "proposition21310_rigidity"),
                H("Arbitrary full competitors have zero shared mass"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("For every natural L, n<j<k<l in Fin L, positive real t, and arbitrary FullScore y in the complete SameFiber of witnessScore, P is zero at every Boolean word, T is zero, A at baseWord equals t, coefficientMass is 4t, and A is not identically zero. Every original stopped schedule-cell numerical reward of witnessScore at label n+1 dominates its baseline reward; this includes the empty and singleton schedules and every empty cell. At least one of the three singleton words agrees with the base word at both possible queried addresses. All competitor words, first-zero classes and labels remain available, and their masses are arbitrary nonnegative reals. In original one-based notation this applies to every 3<=n<j<k<l<=L by subtracting one from the four addresses.")),
                    Paragraph(Text("The proof extracts only the empty-cell total, singleton success rewards and stopped pair-11 rewards from the actual supplier cells. Singleton zero readings force the entire baseline measure onto baseWord. The nonnegative quadratic 1-zj-zk-zl+zj*zk+zj*zl+zk*zl has zero integral under the numerical measure but value one at baseWord. It therefore forbids numerical mass there. Nonnegative P is shared by both measures at the same actual word, so P vanishes everywhere. A finite first-zero partition accounts for all numerical labels and gives the exact coefficient mass without assuming a general cell-to-moment equivalence.")),
                    Paragraph(Text("The obstruction concerns removal of A within the specified complete reward fiber. These are proof weights on one finite cube, not acquisition probabilities. It implies no unrestricted-repair or E_N nonmembership claim and asserts no literature novelty."))),
                DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("joint-reward-fullcell"),
                DeclarationHandle.Create(Owner + "fullCell"), H("Complete N cells"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, original Schedule L and raw Boolean word, fullCell gives the four cells 00,01,10,11 in that order for a distinct ordered pair. Empty schedules use cell zero. Singletons use cells zero and one. Other short-schedule cells are empty."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-catalogcell"),
                DeclarationHandle.Create(Owner + "catalogCell"), H("Both original partitions"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, stop, schedule and word, catalogCell uses the existing stopped cell when stop is true and fullCell when stop is false. Stopped indices zero, one and two embed in Fin 4, whose final cell is empty. Thus the two values of stop denote the complete O and N catalogs respectively."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-catalogreading"),
                DeclarationHandle.Create(Owner + "catalogReading"), H("Every complete cell reward"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, real measure on the full cube, stop, original schedule and Fin 4 cell, catalogReading sums that same measure over precisely the words in the selected original cell. Zero mass and empty cells are included."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-labelreading"),
                DeclarationHandle.Create(Owner + "labelReading"), H("All original numerical and zero labels"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y, stop, schedule, cell and output r in Fin (L+1), labelReading is catalogReading of the baseline when r=0 and of numerical y i when r=i+1. This is the complete reward g of Definition 213.1 with the original first-zero labels."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-schedulereward"),
                DeclarationHandle.Create(Owner + "scheduleReward"), H("One whole table"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y, stop, original schedule and arbitrary map from Fin 4 to Fin (L+1), scheduleReward sums labelReading using that table's output in each cell. Every original output label is allowed independently in every cell."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-completesupport"),
                DeclarationHandle.Create(Owner + "completeSupport"), H("Complete support before anchor subtraction"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, stop and full score y, completeSupport is the supremum of scheduleReward over every original empty, singleton and distinct ordered pair schedule and every cell-label table. This finite range is exactly the maximization over all cell maxima and schedules in Definition 213.1. The empty cells added for short and stopped tables contribute zero."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-anchor"),
                DeclarationHandle.Create(Owner + "anchor"), H("The original head-pair anchor"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, anchor sums A over all first-zero classes whose zero-based address is at least two, C over the two earlier classes, every P once and T once. Original index n is the zero-based address plus one, so the late condition is the original inequality 3<=n."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-completecost"),
                DeclarationHandle.Create(Owner + "completeCost"), H("Complete excess over the anchor"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, stop and full score, completeCost is completeSupport minus anchor. True stop denotes Delta O and false stop denotes Delta N."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-feature"),
                DeclarationHandle.Create(Owner + "feature"), H("Original quadratic coordinates"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, word and coordinate in Unit plus singleton addresses plus ordered distinct pairs, feature is the constant one, the selected bit, or the product of the selected two bits. The coordinate carrier uses Schedule L as an index set; it does not replace the words or their first-zero classes."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-moments"),
                DeclarationHandle.Create(Owner + "moments"), H("Actual full-cube moments"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and arbitrary real measure mu on the raw Boolean cube, moments mu sums mu times feature in each constant, singleton and ordered pair coordinate."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-momentcone"),
                DeclarationHandle.Create(Owner + "MomentCone"), H("Actual first-zero moment cone"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, first-zero address i and complete quadratic vector v, MomentCone i v means that one actual nonnegative real measure on the entire cube represents v and vanishes outside the original class FirstZero i. No relaxation to independent marginal data is made."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-classbaselinemass"),
                DeclarationHandle.Create(Owner + "classBaselineMass"), H("Baseline mass in each first-zero class"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y and address i, classBaselineMass sums A+P over precisely the original class FirstZero i. Terminal T is separate."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-coupledfeasible"),
                DeclarationHandle.Create(Owner + "CoupledFeasible"), H("The coupled common-P constraints"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, full score y and families x,p of complete quadratic vectors indexed by every first-zero class, CoupledFeasible requires p, x-p and moments(numerical y i)-p to lie in the corresponding actual MomentCone; x's constant coordinate equals classBaselineMass; and the sum of all x vectors plus T times the terminal feature equals moments(baseline y). The same p is used in both differences, and the last equation is one aggregate equation on the common cube."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-commonmassset"),
                DeclarationHandle.Create(Owner + "commonMassSet"), H("All feasible common masses"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, commonMassSet contains exactly the sums of constant coordinates of p over all x,p satisfying CoupledFeasible. It includes all actual feasible variables and retains a single shared P vector for each class."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-jointmaximum"),
                DeclarationHandle.Create(Owner + "jointMaximum"), H("The coupled optimum J"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, jointMaximum is the supremum of commonMassSet. The theorem below proves that this supremum is an attained greatest element equal to zero for the four-word family."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-coefficientfloor"),
                DeclarationHandle.Create(Owner + "coefficientFloor"), H("The original coefficient floor"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, coefficientFloor is T plus the sum over every first-zero class of the maximum of its baseline mass and its numerical-label mass. It is K floor in Definition 213.7 and Theorem 213.8."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-fibermassset"),
                DeclarationHandle.Create(Owner + "fiberMassSet"), H("All actual fiber coefficient masses"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, fiberMassSet consists of coefficientMass z for all arbitrary nonnegative full scores z in SameFiber z y. All raw words, first-zero classes and original individual rewards remain constrained."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-coefficientminimum"),
                DeclarationHandle.Create(Owner + "coefficientMinimum"), H("The fiber coefficient minimum"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L and full score y, coefficientMinimum is the infimum of fiberMassSet. The theorem below supplies a least element and an actual attaining score for this family, without assuming Theorem 213.8."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("joint-reward-proposition21310-costs"),
                DeclarationHandle.Create(Owner + "proposition21310_costs"), H("Complete N and O costs"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, ordered zero-based addresses n<j<k<l, late address n.val>=2 and positive real t, let y be witnessScore. Its entire beta function is 2t at n and zero elsewhere, its original anchor is t, and both complete supports are 3t and both complete costs are 2t. For every original schedule, every N or O cell and every empty cell, numerical label n+1 dominates the zero-label reward. The proof bounds every label choice in every complete table and exhibits the constant numerical-label table attaining 3t; it uses no restriction on competitor supports."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("joint-reward-proposition21310-cone-minimum"),
                DeclarationHandle.Create(Owner + "proposition21310_cone_minimum"), H("Attained joint and coefficient extrema"),
                StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every L, n<j<k<l and positive real t, let y be witnessScore. Zero is a greatest element of commonMassSet and jointMaximum is zero. For all actual feasible x,p, every vector p i is zero. The value 4t is a least element of fiberMassSet, coefficientMinimum is 4t, coefficientFloor is 3t and the floor is strictly smaller than the minimum. An explicit feasible choice takes x at class n to be the moments of the actual base point of mass t, all other x to be zero and the shared p to be zero in every class. The source score itself attains the coefficient minimum. The cone proof chooses one P measure, one A residual and one C residual for each class, assembles the aggregate baseline, and applies the same nonnegative quadratic support separation. Direct polynomial formulas recover actual stopped readings from the complete moment vector; no general attainment or independent-P reconstruction theorem is assumed."))), DescribeRole.Theorem))));
}
